source.bookSourceComment:
// v 2023-10-13
// by Thomas喲
//支持  搜索分享链接  获取歌单
//例1： https://www.kuwo.cn/playlist_detail/1082685104
//例2： https://m.kuwo.cn/newh5app/playlist_detail/1082685104
[//自定义歌单_开始
// 歌单示例
{
	// debug1 是歌单标识
	// 具有唯一性(不能重复，也不能命名为 "id" )
	"debug1": {
		"name": "歌单示例1", // 书籍名称
		"uname": "Thomas喲", // 书籍作者
		"tag": ["本地歌单","测试",], // 标签
		"desc": "歌单示例1，测试", // 简介
		"img": "",// 封面链接
		"musicList": [



		], // 歌曲目录
		},
	"debug2": {
		}
},
// txt按照歌单示例的格式填写
[file]/storage/emulated/0/自定义路径/本地歌单示例.txt[/file]
]//自定义歌单_结束

source.exploreUrl:
@js:
eval(String(source.loginUrl));
sort = [];
push = (title, url, type) => sort.push({
    title: title,
    url: url,
    style: {
        layout_flexGrow: 1,
        layout_flexBasisPercent: type
    }
});
$$ = (ura, urb) => `data:;base64,{{java.base64Encode("${ura+type}发现${urb||""}")}\},{"type":"${type}"}`;



if ($["推荐"]) {
    push('༺ 推荐 ༻', null, 1);
    push('每日推荐', $$('rcm/index/playlist?id=rcm'), 0.4)
    push('自定歌单', $$('', `${type}本地`), 0.4)
    push('最新精选', $$('classify/playlist/getRcmPlayList?order=new&pn="+page+"'), 0.4)
    push('热门精选', $$('classify/playlist/getRcmPlayList?order=hot&pn="+page+"'), 0.4);
}



if ($["排行"]) {
    push('༺ 排行 ༻', null, 1);
    result = java.hexEncodeToString(`bang/bang/bangMenu?${type}加载`);
    data = eval(String(source.loginUrl));
    JSON.parse(data).map($ => {
        list = $.list.map($ => ({
            name: $.name,
            desc: $.intro,
            img: $.pic,
            sid: $.sourceid
        }));
        list = java.base64Encode(JSON.stringify(list));
        push($.name, $$(list + type + "加载" + type + "排行"), 0.25);
    });
}


x = false;
for (key of Arr.slice(2)) {
    if ($[key]) {
        x = true;
        break;
    }
}
if (x) {
    result = java.hexEncodeToString(`playlist/getTagList?${type}加载`);
    data = eval(String(source.loginUrl));
    JSON.parse(data).map(data => {
        if (data.data.length) {
            name = data.name.replace('流派', '');
            if ($[name]) {
                push('༺ ' + name + ' ༻', null, 1, 1);
                data.data.map(data => {
                    push(data.name, $$(`classify/playlist/getTagPlayList?id=${data.id}&pn="+page+"`), 0.2);
                });
            }
        }
    });
}

if (!sort.length) push("所有的分类都关了，登录打开", null, 1);
JSON.stringify(sort);

